/*
 * Turns a menu file (camelCase JSON) into the document the renderer (Web/discmenus.js) consumes, which the
 * plugin's server normally builds with Api/RenderableBuilder.cs and serialises in PascalCase. This lets the
 * renderer run in preview mode with no Jellyfin server (the editor's live preview does that against a real
 * server; a static website can't).
 *
 *   toRenderable(menu)                  -> the document, with stand-ins for what only a server knows
 *   toRenderable(menu, { fake: false }) -> exactly what the server produces for a menu bound to nothing
 *   fakeExtras(menu)                    -> { standInId: { key, type, durationSec } } to describe what a click "plays"
 *
 * It must stay in step with RenderableBuilder.cs; tests/js/preview-adapter.test.js compares it, byte for byte, with
 * golden files generated by the C# code (tests/fixtures/renderable). Works in a browser (global MenuToRenderable)
 * and in Node (module.exports). No dependencies.
 */
(function (root, factory) {
    var api = factory();
    if (typeof module === 'object' && module.exports) {
        module.exports = api;
    } else {
        root.MenuToRenderable = api;
    }
})(typeof self !== 'undefined' ? self : this, function () {
    'use strict';

    var NUMBER_OF_FAKE_CHAPTERS = 12;
    var FAKE_THEME_SONG = 'preview-theme';
    var FAKE_TRAILER = 'preview-trailer';

    // "__proto__" is the one key that, assigned like any other, would change the prototype of the object being
    // built instead of adding a property. A valid menu never has it (the schema forbids unknown properties), but
    // this can see text that hasn't been validated yet, so it is simply never copied.
    function copyable(key) {
        return key !== '__proto__';
    }

    // Property names become PascalCase ("tmdbFilePath" -> "TmdbFilePath"), as in the server's JSON. Only used on
    // subtrees whose keys are all property names (background, theme, layout, audio); never on dictionaries whose
    // keys are menu keys.
    function pascal(value) {
        if (Array.isArray(value)) {
            return value.map(pascal);
        }

        if (value && typeof value === 'object') {
            var out = {};
            Object.keys(value).filter(copyable).forEach(function (k) {
                out[k.charAt(0).toUpperCase() + k.slice(1)] = pascal(value[k]);
            });
            return out;
        }

        return value;
    }

    function has(obj, key) {
        return Object.prototype.hasOwnProperty.call(obj, key) && obj[key] !== null && obj[key] !== undefined;
    }

    // A small stable hash so a stand-in id is the same every time for the same extra key.
    function hash(text) {
        var h = 2166136261;
        for (var i = 0; i < text.length; i++) {
            h ^= text.charCodeAt(i);
            h = Math.imul(h, 16777619) >>> 0;
        }

        return h.toString(16).padStart(8, '0');
    }

    function fakeId(extraKey) {
        var a = hash(extraKey);
        var b = hash(a + extraKey);
        return a + '-' + b.slice(0, 4) + '-4' + b.slice(4, 7) + '-8' + b.slice(1, 4) + '-' + a + b.slice(0, 4);
    }

    // The entry fields every action shares, then the ones specific to its action: exactly the properties
    // RenderableEntry carries (anything else in the file is dropped, as on the server).
    function entry(e, opts, extraKeys) {
        var out = { Action: e.action, Label: e.label };
        ['position', 'style', 'image', 'imageFocus'].forEach(function (k) {
            if (has(e, k)) {
                out[k.charAt(0).toUpperCase() + k.slice(1)] = pascal(e[k]);
            }
        });

        switch (e.action) {
            case 'playFeature':
                if (has(e, 'startChapter')) {
                    out.StartChapter = e.startChapter;
                }

                break;
            case 'playExtra':
                if (opts.fake && extraKeys[e.extra]) {
                    out.ItemId = fakeId(e.extra);
                }

                break;
            case 'playSequence':
                // The server always sends the list, empty when nothing is bound.
                out.ItemIds = opts.fake
                    ? (e.extras || []).filter(function (k) { return extraKeys[k]; }).map(fakeId)
                    : [];
                break;
            case 'submenu':
                out.Menu = e.menu;
                break;
            case 'chapters':
                if (has(e, 'perPage')) {
                    out.PerPage = e.perPage;
                }

                if (has(e, 'menu')) {
                    out.Menu = e.menu;
                }

                break;
            default: // back, home: nothing more
                break;
        }

        return out;
    }

    function allMenus(menu) {
        return Object.keys(menu.menus || {}).map(function (k) { return menu.menus[k]; });
    }

    function usesChapters(menu) {
        return allMenus(menu).some(function (m) {
            return (m.entries || []).some(function (e) {
                return e.action === 'chapters' || (e.action === 'playFeature' && has(e, 'startChapter'));
            });
        });
    }

    function usesTrailer(menu) {
        function trailer(b) {
            return !!b && b.source === 'trailer';
        }

        return trailer(menu.background) || allMenus(menu).some(function (m) { return trailer(m.background); });
    }

    function usesThemeSong(menu) {
        function theme(a) {
            return !!a && !!a.music && a.music.source === 'themeSong';
        }

        return theme(menu.audio) || allMenus(menu).some(function (m) { return theme(m.audio); });
    }

    function toRenderable(menu, options) {
        if (!menu || typeof menu !== 'object' || Array.isArray(menu)) {
            throw new TypeError('a menu must be a JSON object');
        }

        var opts = { fake: !options || options.fake !== false };
        var extraKeys = menu.extras || {};

        var menus = {};
        Object.keys(menu.menus || {}).filter(copyable).forEach(function (key) {
            var m = menu.menus[key];
            var out = { Title: m.title };
            ['background', 'theme', 'layout', 'audio'].forEach(function (k) {
                if (has(m, k)) {
                    out[k.charAt(0).toUpperCase() + k.slice(1)] = pascal(m[k]);
                }
            });
            out.Entries = (m.entries || []).map(function (e) { return entry(e, opts, extraKeys); });
            menus[key] = out;
        });

        // Jellyfin writes GUIDs as 32 lower-case hex digits with no hyphens (its "N" format).
        var doc = { MenuId: String(menu.menuId).toLowerCase().replace(/-/g, ''), Root: menu.root };
        ['background', 'theme', 'layout', 'audio'].forEach(function (k) {
            if (has(menu, k)) {
                doc[k.charAt(0).toUpperCase() + k.slice(1)] = pascal(menu[k]);
            }
        });

        if (opts.fake) {
            // What only a server knows: stand-ins, and only for what the menu actually uses (as on the server).
            if (usesThemeSong(menu)) {
                doc.ThemeSongs = [FAKE_THEME_SONG];
            }

            if (usesTrailer(menu)) {
                doc.Trailers = [{ Kind: 'local', ItemId: FAKE_TRAILER, Name: 'Trailer' }];
            }

            if (usesChapters(menu)) {
                doc.Chapters = [];
                for (var i = 0; i < NUMBER_OF_FAKE_CHAPTERS; i++) {
                    doc.Chapters.push({ Index: i, Name: 'Chapter ' + (i + 1), StartTicks: i * 3000000000, HasImage: false });
                }
            }
        }

        doc.Menus = menus;
        return doc;
    }

    // Describes a stand-in id, so a preview can say "would play: Making Of (Behind the Scenes, 25:00)".
    function fakeExtras(menu) {
        var out = {};
        Object.keys(menu.extras || {}).forEach(function (key) {
            var spec = menu.extras[key] || {};
            out[fakeId(key)] = { key: key, type: spec.type, durationSec: spec.durationSec };
        });
        return out;
    }

    return { toRenderable: toRenderable, fakeExtras: fakeExtras, FAKE_TRAILER: FAKE_TRAILER, FAKE_THEME_SONG: FAKE_THEME_SONG };
});
